import React, { useState, useEffect } from "react";

function Courses() {
  const [courses, setCourses] = useState([]);
  const [formData, setFormData] = useState({
    name: "",
    credits: "",
    instructor: "",
  });
  const [editingId, setEditingId] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState("");

  // Fetch courses from backend
  const fetchCourses = async () => {
    try {
      setIsLoading(true);
      const response = await fetch("http://localhost:5000/api/courses");
      const data = await response.json();
      setCourses(data);
      setError("");
    } catch (err) {
      setError("Failed to fetch courses. Please try again later.");
      console.error("Error:", err);
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    fetchCourses();
  }, []);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: name === 'credits' ? parseInt(value) || '' : value
    }));
  };

  const resetForm = () => {
    setFormData({ name: "", credits: "", instructor: "" });
    setEditingId(null);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    setError("");

    try {
      const url = editingId 
        ? `http://localhost:5000/api/courses/${editingId}`
        : 'http://localhost:5000/api/courses';

      const method = editingId ? 'PUT' : 'POST';

      const response = await fetch(url, {
        method,
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(formData),
      });

      if (!response.ok) {
        throw new Error('Failed to save course');
      }

      await fetchCourses();
      resetForm();
    } catch (err) {
      setError("Failed to save course. Please try again.");
      console.error("Error:", err);
    }
  };

  const handleEdit = (course) => {
    setFormData({
      name: course.name,
      credits: course.credits,
      instructor: course.instructor,
    });
    setEditingId(course._id);
  };

  const handleDelete = async (id) => {
    if (!window.confirm("Are you sure you want to delete this course?")) return;

    try {
      const response = await fetch(`http://localhost:5000/api/courses/${id}`, {
        method: "DELETE",
      });

      if (!response.ok) {
        throw new Error('Failed to delete course');
      }

      await fetchCourses();
      if (editingId === id) resetForm();
    } catch (err) {
      setError("Failed to delete course. Please try again.");
      console.error("Error:", err);
    }
  };

  return (
    <div className="container mt-4">
      <h2 className="mb-4">Course Management</h2>

      {error && <div className="alert alert-danger">{error}</div>}

      <div className="card mb-4">
        <div className="card-header">
          <h5 className="mb-0">{editingId ? 'Edit Course' : 'Add New Course'}</h5>
        </div>
        <div className="card-body">
          <form onSubmit={handleSubmit}>
            <div className="row g-3">
              <div className="col-md-4">
                <label htmlFor="name" className="form-label">Course Name</label>
                <input
                  type="text"
                  id="name"
                  name="name"
                  className="form-control"
                  value={formData.name}
                  onChange={handleInputChange}
                  required
                />
              </div>
              <div className="col-md-3">
                <label htmlFor="credits" className="form-label">Credits</label>
                <input
                  type="number"
                  id="credits"
                  name="credits"
                  className="form-control"
                  value={formData.credits}
                  onChange={handleInputChange}
                  min="1"
                  required
                />
              </div>
              <div className="col-md-3">
                <label htmlFor="instructor" className="form-label">Instructor</label>
                <input
                  type="text"
                  id="instructor"
                  name="instructor"
                  className="form-control"
                  value={formData.instructor}
                  onChange={handleInputChange}
                  required
                />
              </div>
              <div className="col-md-2 d-flex align-items-end">
                <div className="d-grid gap-2 w-100">
                  <button type="submit" className="btn btn-primary" disabled={isLoading}>
                    {isLoading ? 'Saving...' : editingId ? 'Update' : 'Add Course'}
                  </button>
                  {editingId && (
                    <button 
                      type="button" 
                      className="btn btn-outline-secondary"
                      onClick={resetForm}
                      disabled={isLoading}
                    >
                      Cancel
                    </button>
                  )}
                </div>
              </div>
            </div>
          </form>
        </div>
      </div>

      <div className="card">
        <div className="card-header">
          <h5 className="mb-0">Course List</h5>
        </div>
        <div className="card-body">
          {isLoading && courses.length === 0 ? (
            <div className="text-center py-4">
              <div className="spinner-border text-primary" role="status">
                <span className="visually-hidden">Loading...</span>
              </div>
            </div>
          ) : courses.length === 0 ? (
            <div className="text-center py-4 text-muted">No courses found. Add your first course above.</div>
          ) : (
            <div className="table-responsive">
              <table className="table table-hover">
                <thead className="table-light">
                  <tr>
                    <th>#</th>
                    <th>Course Name</th>
                    <th>Credits</th>
                    <th>Instructor</th>
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {courses.map((course, index) => (
                    <tr key={course._id}>
                      <td>{index + 1}</td>
                      <td>{course.name}</td>
                      <td>{course.credits}</td>
                      <td>{course.instructor}</td>
                      <td>
                        <div className="btn-group btn-group-sm">
                          <button
                            className="btn btn-outline-primary"
                            onClick={() => handleEdit(course)}
                            disabled={isLoading}
                          >
                            Edit
                          </button>
                          <button
                            className="btn btn-outline-danger"
                            onClick={() => handleDelete(course._id)}
                            disabled={isLoading}
                          >
                            Delete
                          </button>
                        </div>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}

export default Courses;
